static void ach_view_load_after(int slot, int masked);
static void ach_view_install(void);
static int ach_view_on = 1;                             /* the game file's key achievement_materia_view (yes unless it says no) */
static BOOL stock_row(int row, int *number, int *quantity);  /* the item list in whichever format is live: see "the DLL's own use of the item list" */
static void stock_row_put(int row, int number, int quantity, const char *routine);
