/* One word of a `slots` line: its first slot type and how many slots it is.
   A pair or chain is that type once, then the type after it for the rest. */
static BOOL slot_word(const char *p, const char *word_end, int *first, int *count)
{
    static const char *const chains[] = { "chain3", "chain4", "chain5", "chain6", "chain7", "chain8" };
    static const char *const plain_chains[] = { "chain3_nogrowth", "chain4_nogrowth", "chain5_nogrowth",
                                                "chain6_nogrowth", "chain7_nogrowth", "chain8_nogrowth" };
    int i;

    if (word_is(p, word_end, "pair")) *first = 6, *count = 2;
    else if (word_is(p, word_end, "single")) *first = 5, *count = 1;
    else if (word_is(p, word_end, "pair_nogrowth")) *first = 2, *count = 2;
    else if (word_is(p, word_end, "single_nogrowth")) *first = 1, *count = 1;
    else if (word_is(p, word_end, "none")) *first = 0, *count = 0;
    else {
        for (i = 0; i < 6; i++) {
            if (word_is(p, word_end, chains[i])) { *first = 6, *count = i + 3; return TRUE; }
            if (word_is(p, word_end, plain_chains[i])) { *first = 2, *count = i + 3; return TRUE; }
        }
        return FALSE;
    }
    return TRUE;
}

static const char slots_problem[] =
    "slots must be a list of: pair, single, chain3 to chain8, none (add _nogrowth for slots that give no AP)";

/* FUN_005cf0fc copies the staged kernel spells into the slots, just before
   the battle command list is built. The game only gives a character the
   Magic command for a magic materia, so add it here when an extended spell
   is on its way, as the game's own materia handlers do. */
static void __cdecl fill_magic_slots_hook(void)
{
    int i;

    int magic = 0, summon = 0;

    link_chains();
    ((void (__cdecl *)(void))FN_FILL_MAGIC_SLOTS)();
    for (i = 0; i < spell_count; i++)
        if (spell_granted(i)) {
            if (spells[i].is_summon)
                summon = 1;
            else
                magic = 1;
        }
    if (magic) {
        ((int (__cdecl *)(char))FN_ADD_COMMAND)(2);
        if (*(BYTE *)ADDR_HAS_MAGIC_FLAG == 0)
            *(BYTE *)ADDR_HAS_MAGIC_FLAG = 1;
    }
    if (summon) {
        ((int (__cdecl *)(char))FN_ADD_COMMAND)(3);
        if (*(BYTE *)ADDR_HAS_SUMMON_FLAG == 0)
            *(BYTE *)ADDR_HAS_SUMMON_FLAG = 1;
    }
}

/* FUN_005cea58 copies each kernel summon's uses into its slot, the last thing done to the summon
   slots in a rebuild. The extended summons the character's materia grant are then put into the
   slots still free: handle, MP cost, uses, targeting. Uses are the game's rule: one per level of
   each materia that grants it. A character has sixteen summon slots in all. */
/* Uses per battle a summon materia at `level` gives an extended summon: the number the materia
   file's `uses` line has for that level, or the level itself (the game's rule) without one. */
static int summon_uses_at(BYTE materia, int level)
{
    const BYTE *record = materia_base + materia * MATERIA_RECORD_SIZE;
    BYTE uses = materia_level_value(materia, level);

    /* only a summon materia (type xb) keeps uses there; a magic materia keeps spells */
    return (record[0x0d] & 0x0f) != 0x0b || uses == 0xff || uses == 0 ? level : uses;
}

static void __cdecl summon_uses_hook(void)
{
    const DWORD *materia = (const DWORD *)ADDR_REBUILD_MATERIA;
    BYTE *slots;
    int i, g, m, k, added = 0, dropped = 0;

    ((void (__cdecl *)(void))FN_SUMMON_USES)();
    if (!*(BYTE **)ADDR_REBUILD_RECORD)
        return;
    slots = *(BYTE **)ADDR_REBUILD_RECORD + 0x108 + SUMMON_SLOT_FIRST * 8;
    for (i = 0; i < spell_count; i++) {
        const struct spell *spell = &spells[i];
        int uses = 0;
        BYTE handle, *slot;

        if (!spell->is_summon || !spell_granted(i))
            continue;
        for (g = 0; g < spell->grant_count; g++)
            for (m = 0; m < 16; m++)
                if ((BYTE)materia[m] == spell->grant_materia[g]) {
                    int level = materia_level(spell->grant_materia[g], materia[m] >> 8);

                    if (level >= spell->grant_level[g])
                        uses += summon_uses_at(spell->grant_materia[g], level);
                }
        for (k = 0; k < SUMMON_SLOT_COUNT && slots[k * 8] != 0xff; k++)
            ;
        handle = k < SUMMON_SLOT_COUNT ? handle_for_id(spell->id) : 0xff;
        if (handle == 0xff) {
            dropped++;
            continue;
        }
        slot = slots + k * 8;
        slot[0] = handle;
        slot[1] = slot_mp_byte(spell->record);
        slot[2] = spell->grant_any ? 0xff : (BYTE)(uses > 0xfe ? 0xfe : uses < 1 ? 1 : uses);
        /* Quadra Magic, and MP Turbo and the absorb, steal and cut flags, from the support materia
           linked to the granting materia; the game raises the MP cost for MP Turbo after this */
        slot[3] = spell_support ? spell_support[i].quadra_count : 0;
        slot[4] = spell_support ? spell_support[i].quadra_uses : 0;
        slot[7] = spell_support ? spell_support[i].flags : 0;
        slot[6] = 0;
        slot[5] = spell->record[REC_TARGET_FLAGS];
        added++;
    }
    if (added || dropped)
        log_line("rebuild: %d extended summon(s) put in the summon list%s", added,
                 dropped ? "; some left out, all sixteen summon slots are in use" : "");
}

/* FUN_005ce996 handles one summon materia: it reads the kernel summon from the materia's first
   attribute byte and uses it as a slot number. A summon materia that holds only extended summons
   has ff there, which would send the game's writes far outside the summon slots, so that case is
   handled here: nothing to add (summon_uses_hook does it), and for the Materia menu's panel the
   first extended summon it grants, with the level as its number of uses. */
static void __cdecl summon_materia_hook(unsigned materia_arg, DWORD ap)
{
    BYTE materia = (BYTE)materia_arg;
    int level, i, g;

    if (materia_base[materia * MATERIA_RECORD_SIZE + 0x0e] != 0xff) {
        ((void (__cdecl *)(unsigned, DWORD))FN_SUMMON_MATERIA)(materia_arg, ap);
        return;
    }
    ((int (__cdecl *)(unsigned, DWORD))FN_MATERIA_LEVEL)(materia_arg, ap);
    level = materia_level(materia, ap);
    if (!*(BYTE *)ADDR_DESCRIBE_MODE)
        return;
    for (i = 0; i < spell_count; i++)
        for (g = 0; spells[i].is_summon && g < spells[i].grant_count; g++)
            if (spells[i].grant_materia[g] == materia) {
                BYTE *info = *(BYTE **)ADDR_MATERIA_INFO;

                panel_ids[0] = spells[i].id;
                info[INFO_ABILITIES] = PANEL_HANDLE_FIRST;
                info[INFO_ABILITIES + 1] = (BYTE)summon_uses_at(materia, level);
                *(DWORD *)ADDR_PANEL_TYPE = 2;
                return;
            }
}

/* ---- Support materia -------------------------------------------------------- */

static void clear_spell_support(void)
{
    BYTE *bytes = (BYTE *)spell_support;
    unsigned i;

    for (i = 0; spell_support && i < (unsigned)spell_count * sizeof *spell_support; i++)
        bytes[i] = 0;
    mega_all_uses = 0;
}

/* Whether a materia with this much AP grants spell `i`. */
static BOOL materia_grants(int i, BYTE materia, DWORD ap)
{
    int g;

    for (g = 0; g < spells[i].grant_count; g++)
        if (spells[i].grant_materia[g] == materia && materia_level(materia, ap) >= spells[i].grant_level[g])
            return TRUE;
    return FALSE;
}

static void new_characters_joining(void);

static void __cdecl rebuild_start_hook(int character, int record)
{
    int i;

    for (i = 0; i < COUNTER_ENTRIES && (BYTE)character < 3; i++)
        counter_ids[(BYTE)character][i] = 0;
    clear_spell_support();
    rebuild_party_slot = (signed char)character;
    new_characters_joining();
    ((void (__cdecl *)(int, int))FN_REBUILD_START)(character, record);
}

/* The four hooks below follow the game's own arithmetic for the kernel
   spells of the linked materia, applied to the extended spells it grants. */

static void __cdecl all_magic_hook(unsigned uses, unsigned materia, DWORD ap)
{
    int i;

    ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_ALL_MAGIC)(uses, materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (materia_grants(i, (BYTE)materia, ap))
            spell_support[i].all_uses += (BYTE)uses;
}

static void __cdecl quadra_magic_hook(unsigned uses, unsigned materia, DWORD ap)
{
    int i;

    ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_QUADRA_MAGIC)(uses, materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (materia_grants(i, (BYTE)materia, ap)) {
            spell_support[i].quadra_count++;
            spell_support[i].quadra_uses += (BYTE)uses;
        }
}

static void __cdecl turbo_magic_hook(unsigned level, unsigned materia, DWORD ap)
{
    int i;

    ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_TURBO_MAGIC)(level, materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (materia_grants(i, (BYTE)materia, ap)) {
            int turbo = (spell_support[i].flags >> 5) + (BYTE)level;

            if (turbo > 5)
                turbo = 5;
            spell_support[i].flags = (BYTE)((spell_support[i].flags & 0x1f) | turbo << 5);
        }
}

static void __cdecl flags_magic_hook(unsigned materia, DWORD ap)
{
    int i;

    ((void (__cdecl *)(unsigned, DWORD))FN_FLAGS_MAGIC)(materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (materia_grants(i, (BYTE)materia, ap))
            spell_support[i].flags |= *(BYTE *)ADDR_SUPPORT_FLAG;
}

/* FUN_005ccf03 runs for each equipped materia; for Mega All it adds its
   level to the All uses of every magic slot. */
static void __cdecl mega_all_hook(DWORD materia)
{
    BYTE id = (BYTE)materia;

    ((void (__cdecl *)(DWORD))FN_MEGA_ALL)(materia);
    if (id != 0xff && (materia_base[id * MATERIA_RECORD_SIZE + 0x0d] & 0x0f) == MATERIA_TYPE_MEGA_ALL)
    {
        int level = materia_level(id, materia >> 8);

        mega_all_uses += (BYTE)(level > MATERIA_GAME_LEVELS ? MATERIA_GAME_LEVELS : level);   /* as the game's own count */
    }
}

/* FUN_005cc2a8 adds the linked magic materia's highest learned kernel spell
   to the counter list. With extended spells the rule becomes: the last
   learned spell in the materia's ability list, as the Materia menu shows it
   (by level, kernel spells before extended ones, then file order). If that
   is an extended spell the entry is given to it: its ID byte becomes a mark
   and the real ID is kept beside it. */
static void __cdecl counter_magic_hook(unsigned support_level, unsigned materia_arg, DWORD ap)
{
    BYTE materia = (BYTE)materia_arg;
    const BYTE *taught = materia_base + materia * MATERIA_RECORD_SIZE + 0x0e;
    int before = *(int *)ADDR_COUNTER_COUNT, count, level, kernel_level, best = -1, best_level = 0;
    int i, g, index, character;
    BYTE *record, *entry;

    ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_COUNTER_MAGIC)(support_level, materia_arg, ap);
    level = materia_level(materia, ap);
    for (kernel_level = level > MATERIA_GAME_LEVELS ? MATERIA_GAME_LEVELS : level;
         kernel_level >= 1 && taught[kernel_level - 1] == 0xff; kernel_level--)
        ;
    for (i = 0; i < spell_count; i++)
        for (g = 0; g < spells[i].grant_count; g++)
            if (spells[i].grant_materia[g] == materia && spells[i].grant_level[g] <= level &&
                spells[i].grant_level[g] >= best_level) {
                best = i;
                best_level = spells[i].grant_level[g];
            }
    if (best < 0 || best_level < kernel_level)
        return;
    record = *(BYTE **)ADDR_REBUILD_RECORD;
    character = (int)(((DWORD)record - ADDR_CHARACTER_RECORD) / CHARACTER_STRIDE);
    if (((DWORD)record - ADDR_CHARACTER_RECORD) % CHARACTER_STRIDE || character < 0 || character > 2)
        return;
    count = *(int *)ADDR_COUNTER_COUNT;
    if (count > before) {
        index = before;                 /* take over the entry the game just added */
    } else {
        if (count < 0 || count >= COUNTER_ENTRIES)
            return;
        index = count;                  /* no kernel spell learned: add the entry as the game would */
        entry = record + CHR_COUNTERS + index * 3;
        entry[0] = (BYTE)(*(DWORD *)ADDR_COUNTER_TYPE + *(WORD *)ADDR_COUNTER_VARIANT);
        entry[2] = *(BYTE *)(ADDR_SUPPORT_VALUES + (BYTE)support_level);
        *(int *)ADDR_COUNTER_COUNT = count + 1;
    }
    entry = record + CHR_COUNTERS + index * 3;
    entry[1] = (BYTE)(COUNTER_MARK_FIRST + index);
    counter_ids[character][index] = spells[best].id;
    log_line("rebuild: character %d counter entry %d (type %d) uses ID %d", character, index, entry[0], spells[best].id);
}

/* FUN_005c8eeb turns a counter entry's ID byte into the command and attack
   to queue, and returns the attack's targeting flags. A marked entry queues
   its extended spell as a magic command under its real ID. */
static unsigned __cdecl counter_pick_hook(int actor, int kind, unsigned id, unsigned *out)
{
    int index = (int)(BYTE)id - COUNTER_MARK_FIRST;
    const BYTE *record = NULL;

    if (actor >= 0 && actor < 3 && index >= 0 && index < COUNTER_ENTRIES && counter_ids[actor][index])
        record = ext_record(counter_ids[actor][index]);
    if (!record)
        return ((unsigned (__cdecl *)(int, int, unsigned, unsigned *))FN_COUNTER_PICK)(actor, kind, id, out);
    out[0] = spell_is_summon(counter_ids[actor][index]) ? 3 : 2;
    out[1] = counter_ids[actor][index];
    log_line("counter: actor %d casts ID %d from counter entry %d", actor, out[1], index);
    return record[REC_TARGET_FLAGS];
}

/* ---- Support materia linked to a summon materia ------------------------------
   The game's routines for a summon partner take the kernel summon from the materia's first
   attribute byte and use it as an index: Quadra Magic into two 16-entry arrays, MP Turbo and
   the absorb / steal / cut flags into the slots (walking the attribute bytes as if they were
   spell numbers), the counter kinds into the counter list. For a materia that holds only
   extended summons that byte is ff, and the first three would write far outside their targets,
   so the game's routine is not run for it. Either way the same arithmetic is applied to the
   extended summons the materia grants; summon_uses_hook puts the results in their slots. */
#define SITE_SUMMON_QUADRA      0x005ccb8du  /* in FUN_005ccb01 */
#define FN_SUMMON_QUADRA        0x005ccca5u  /* FUN_005ccca5(uses, materia, ap) */
#define SITE_SUMMON_TURBO       0x005cc4b5u  /* in FUN_005cc429 */
#define FN_SUMMON_TURBO         0x005cc4dfu  /* FUN_005cc4df(level, materia, ap) */
#define SITE_SUMMON_FLAGS       0x005cc809u  /* in FUN_005cc773 */
#define FN_SUMMON_FLAGS         0x005cc838u  /* FUN_005cc838(materia, ap) */
#define FN_SUMMON_COUNTER       0x005cc38eu  /* FUN_005cc38e(support level, materia, ap) */
static const DWORD summon_counter_sites[] = { 0x005cbf1c, 0x005cc024 };    /* in FUN_005cbe82, FUN_005cbf4b */

static BOOL holds_kernel_summon(BYTE materia)
{
    return materia_base[materia * MATERIA_RECORD_SIZE + 0x0e] != 0xff;
}

static BOOL grants_summon(int i, BYTE materia, DWORD ap)
{
    return spells[i].is_summon && materia_grants(i, materia, ap);
}

static void __cdecl summon_quadra_hook(unsigned uses, unsigned materia, DWORD ap)
{
    int i;

    if (holds_kernel_summon((BYTE)materia))
        ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_SUMMON_QUADRA)(uses, materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (grants_summon(i, (BYTE)materia, ap)) {
            spell_support[i].quadra_count++;
            spell_support[i].quadra_uses += (BYTE)uses;
        }
}

static void __cdecl summon_turbo_hook(unsigned level, unsigned materia, DWORD ap)
{
    int i;

    if (holds_kernel_summon((BYTE)materia))
        ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_SUMMON_TURBO)(level, materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (grants_summon(i, (BYTE)materia, ap)) {
            int turbo = (spell_support[i].flags >> 5) + (BYTE)level;

            if (turbo > 5)
                turbo = 5;
            spell_support[i].flags = (BYTE)((spell_support[i].flags & 0x1f) | turbo << 5);
        }
}

static void __cdecl summon_flags_hook(unsigned materia, DWORD ap)
{
    int i;

    if (holds_kernel_summon((BYTE)materia))
        ((void (__cdecl *)(unsigned, DWORD))FN_SUMMON_FLAGS)(materia, ap);
    for (i = 0; spell_support && i < spell_count; i++)
        if (grants_summon(i, (BYTE)materia, ap))
            spell_support[i].flags |= *(BYTE *)ADDR_SUPPORT_FLAG;
}

/* Counter, Magic Counter, Sneak Attack and Final Attack with a summon materia: the game adds a
   counter entry holding the kernel summon. If the materia grants an extended summon at its level
   the entry is given to that one instead (the first in file order), marked as for magic. */
static void __cdecl summon_counter_hook(unsigned support_level, unsigned materia_arg, DWORD ap)
{
    BYTE materia = (BYTE)materia_arg;
    int before = *(int *)ADDR_COUNTER_COUNT, count, i, index, character, best = -1;
    BYTE *record, *entry;

    for (i = 0; i < spell_count && best < 0; i++)
        if (grants_summon(i, materia, ap))
            best = i;
    if (!holds_kernel_summon(materia) && best < 0)
        return;                         /* nothing it could cast */
    ((void (__cdecl *)(unsigned, unsigned, DWORD))FN_SUMMON_COUNTER)(support_level, materia_arg, ap);
    if (best < 0)
        return;
    record = *(BYTE **)ADDR_REBUILD_RECORD;
    character = (int)(((DWORD)record - ADDR_CHARACTER_RECORD) / CHARACTER_STRIDE);
    count = *(int *)ADDR_COUNTER_COUNT;
    if (((DWORD)record - ADDR_CHARACTER_RECORD) % CHARACTER_STRIDE || character < 0 || character > 2 ||
        count <= before) {
        if (!holds_kernel_summon(materia) && count > before)
            *(int *)ADDR_COUNTER_COUNT = before;        /* an entry for summon ff: take it back */
        return;
    }
    index = before;
    entry = record + CHR_COUNTERS + index * 3;
    entry[1] = (BYTE)(COUNTER_MARK_FIRST + index);
    counter_ids[character][index] = spells[best].id;
    log_line("rebuild: character %d counter entry %d (type %d) uses summon ID %d", character, index, entry[0],
             spells[best].id);
}

/* MP cost with MP Turbo, as the game works it out at the end of a rebuild. */
static BYTE turbo_mp_cost(BYTE cost, BYTE flags)
{
    unsigned raised = cost + 1 + cost * (unsigned)(flags >> 5) / 10;

    if (!(flags & 0xe0))
        return cost;
    return raised > 0xff ? 0xff : (BYTE)raised;
}

/* ---- Long list and window ------------------------------------------------- */

static int list_rows(int character)
{
    return list_length[character] / MAGIC_COLUMNS;
}

/* Copies the game's visible slots back into the list. */
static void window_store(int character)
{
    const BYTE *slots = spell_slots(character);
    int first = window_base[character] * MAGIC_COLUMNS, i;

    if (!spell_list[character])
        return;
    for (i = 0; i < WINDOW_SLOTS && first + i < list_length[character]; i++)
        copy_bytes(spell_list[character][first + i].image, slots + i * 8, 8);
}

/* Fills the game's visible slots from the list at the current window. */
static void window_load(int character)
{
    BYTE *slots = spell_slots(character);
    int first = window_base[character] * MAGIC_COLUMNS, i;

    if (!spell_list[character])
        return;
    for (i = 0; i < MAGIC_SLOT_COUNT; i++) {
        BYTE *slot = slots + i * 8;
        const struct list_entry *entry = &spell_list[character][first + i];
        BYTE id_byte = 0xff;

        if (i < WINDOW_SLOTS && first + i < list_length[character] && entry->id != NO_SPELL)
            id_byte = ext_record(entry->id) ? handle_for_id(entry->id) : (BYTE)entry->id;
        if (id_byte == 0xff) {
            slot[0] = 0xff;
            slot[1] = slot[2] = slot[3] = slot[4] = slot[5] = slot[6] = slot[7] = 0;
        } else {
            copy_bytes(slot, entry->image, 8);
            slot[0] = id_byte;
        }
    }
}

static void set_window_base(int character, int base)
{
    int last = list_rows(character) - WINDOW_ROWS;

    if (base > last)
        base = last;
    if (base < 0)
        base = 0;
    if (base == window_base[character])
        return;
    window_store(character);
    window_base[character] = base;
    window_load(character);
}

/* Keeps the game's own scrolling going past its 18 rows. The game scrolls
   `grid` within the window; when it reaches either end and the list goes
   on, the window is moved under it and the grid's top row is moved back by
   the same amount, so what is on screen does not change. Returns TRUE if
   the window moved. */
static BOOL slide_window(int character, int *grid)
{
    int visible = grid[GRID_VISIBLE_ROWS], top = grid[GRID_TOP_ROW];
    int last = list_rows(character) - WINDOW_ROWS;
    int base = window_base[character], new_base;

    if (last <= 0 || visible <= 0 || visible > WINDOW_ROWS || top < 0 || top > WINDOW_ROWS - visible)
        return FALSE;
    if (!((top == 0 && base > 0) || (top == WINDOW_ROWS - visible && base < last)))
        return FALSE;
    new_base = base + top - (WINDOW_ROWS - visible) / 2;
    if (new_base > last)
        new_base = last;
    if (new_base < 0)
        new_base = 0;
    if (new_base == base)
        return FALSE;
    set_window_base(character, new_base);
    grid[GRID_TOP_ROW] = base + top - new_base;
    return TRUE;
}

/* ---- Magic order ---------------------------------------------------------------
   The Config menu's Magic order setting puts the game's spells in three groups
   (restore, attack, indirect) in the chosen order, with a fourth group always
   last. An extended spell belongs to one of the three: the one its `order` key
   names, or else the one its record suggests. */
#define ADDR_CONFIG_WORD        0x00dc0e12u  /* bits 10-12: the Magic order setting, 0-5 */
#define ADDR_ORDER_POSITIONS    0x007b7790u  /* 4 bytes per setting: where each group comes */
#define ADDR_KERNEL_ORDER       0x0099dd6cu  /* one byte per kernel spell: group in the top 3 bits */
#define KERNEL_SPELLS           0x36

static int spell_order_group(const struct spell *spell)
{
    const BYTE *record = spell->record;

    if (spell->order_group)
        return spell->order_group - 1;
    if ((*(const WORD *)(record + REC_ELEMENT) & 0x0200) || record[REC_STATUS_CHANGE] >> 6 == 1)
        return 0;                       /* restorative, or takes statuses away */
    return (record[REC_DAMAGE_FORMULA] & 0xf0) ? 1 : 2;     /* does damage: attack; otherwise indirect */
}

/* FUN_005dd700 orders a character's magic slots as the last step of a
   rebuild: group by group, a row dropped when it has no spell. The list is
   then made from those rows, each group's followed by the extended spells of
   that group which the character's materia grant, and the window is put back
   at the top. */
static void __cdecl order_slots_hook(int character)
{
    struct list_entry *list;
    const BYTE *slots, *positions;
    int i, n = 0, added = 0, position, row, setting;

    ((void (__cdecl *)(int))FN_ORDER_SLOTS)(character);
    if (character < 0 || character > 2 || !spell_list[character])
        return;
    list = spell_list[character];
    slots = spell_slots(character);
    setting = *(const WORD *)ADDR_CONFIG_WORD >> 10 & 7;
    positions = (const BYTE *)ADDR_ORDER_POSITIONS + (setting > 5 ? 0 : setting) * 4;
    for (position = 0; position < 4; position++) {
        for (row = 0; row < WINDOW_ROWS; row++) {
            const BYTE *first = slots + row * MAGIC_COLUMNS * 8;
            int group = -1;

            for (i = 0; i < MAGIC_COLUMNS && group < 0; i++)
                if (first[i * 8] < KERNEL_SPELLS)
                    group = *(const BYTE *)(ADDR_KERNEL_ORDER + first[i * 8]) >> 5;
            if (group < 0 || group > 3 || positions[group] != position)
                continue;
            for (i = 0; i < MAGIC_COLUMNS; i++, n++) {
                list[n].id = first[i * 8] == 0xff ? NO_SPELL : first[i * 8];
                copy_bytes(list[n].image, first + i * 8, 8);
            }
        }
        for (i = 0; spell_support && i < spell_count && n < list_capacity - MAGIC_COLUMNS; i++) {
            const BYTE *record = spells[i].record;
            BYTE *image = list[n].image;

            if (!spell_granted(i) || spells[i].is_summon || positions[spell_order_group(&spells[i])] != position)
                continue;
            list[n].id = spells[i].id;
            image[0] = image[6] = 0;
            image[1] = slot_mp_byte(record);
            image[2] = (BYTE)(spell_support[i].all_uses + mega_all_uses);
            image[3] = spell_support[i].quadra_count;
            image[4] = spell_support[i].quadra_uses;
            image[5] = record[REC_TARGET_FLAGS];
            image[7] = spell_support[i].flags;
            n++;
            added++;
        }
        for (; n % MAGIC_COLUMNS; n++) {
            list[n].id = NO_SPELL;
            for (i = 0; i < 8; i++)
                list[n].image[i] = i ? 0 : 0xff;
        }
    }
    /* The game raises the MP cost for MP Turbo itself after this, but only in
       the slots it can see: those that will be in the window. */
    for (i = WINDOW_SLOTS; i < n; i++)
        if (list[i].id != NO_SPELL)
            list[i].image[1] = turbo_mp_cost(list[i].image[1], list[i].image[7]);
    list_length[character] = n;
    window_base[character] = 0;
    scratch_entry[character] = 0;
    window_load(character);
    log_line("rebuild: character %d has %d list rows (%d extended spells), magic order %d", character,
             n / MAGIC_COLUMNS, added, setting);
}

/* Slots loaded from the list hold the record's raw targeting flags. The
   game narrows them (single target unless All is linked) and works out
   which spells can be afforded in FUN_00437679, but only while the actor's
   "stale" bit is set, so set it whenever the window has been reloaded. */
static void mark_slot_flags_stale(int actor)
{
    *(BYTE *)(ADDR_SLOT_FLAGS_STALE + actor * BATTLE_ACTOR_STRIDE) |= 1 << 1;
}

/* FUN_005cfe67 prepares a character's slots as a battle starts. One step
   takes away the All uses of any magic spell whose record cannot switch
   between one target and all, reading the kernel record of the slot's
   one-byte ID. Redo that step for extended spells from their own records,
   in the window and in the rest of the list. */
static void __cdecl battle_slots_hook(int character)
{
    BYTE saved[WINDOW_SLOTS];
    BYTE *slots;
    int first, i;

    if (character < 0 || character > 2 || !spell_list[character]) {
        ((void (__cdecl *)(int))FN_BATTLE_SLOTS)(character);
        return;
    }
    slots = spell_slots(character);
    for (i = 0; i < WINDOW_SLOTS; i++)
        saved[i] = slots[i * 8 + 2];
    ((void (__cdecl *)(int))FN_BATTLE_SLOTS)(character);
    for (i = 0; i < WINDOW_SLOTS; i++) {
        const BYTE *record = ext_record(handle_to_id(slots[i * 8]));

        if (record)
            slots[i * 8 + 2] = (record[REC_TARGET_FLAGS] & 8) ? saved[i] : 0;
    }
    first = window_base[character] * MAGIC_COLUMNS;
    for (i = 0; i < list_length[character]; i++) {
        struct list_entry *entry = &spell_list[character][i];
        const BYTE *record = ext_record(entry->id);

        if (record && !(record[REC_TARGET_FLAGS] & 8) && (i < first || i >= first + WINDOW_SLOTS))
            entry->image[2] = 0;
    }
}

/* FUN_006f4db2(grid): cursor movement and scrolling for one grid. */
static void __cdecl battle_grid_input_hook(int *grid)
{
    DWORD offset = (DWORD)grid - ADDR_BATTLE_MAGIC_GRID;
    int actor = (int)(offset / BATTLE_GRID_STRIDE);

    ((void (__cdecl *)(int *))FN_GRID_INPUT)(grid);
    if (offset % BATTLE_GRID_STRIDE == 0 && actor < 3 && slide_window(actor, grid)) {
        mark_slot_flags_stale(actor);
        ((void (__cdecl *)(int, int))FN_REFRESH_SLOT_FLAGS)(actor, 1);
    }
}

static void __cdecl menu_grid_input_hook(int *grid)
{
    int character = *(int *)ADDR_MENU_CHARACTER;

    ((void (__cdecl *)(int *))FN_GRID_INPUT)(grid);
    if ((DWORD)grid == ADDR_MENU_MAGIC_GRID && character >= 0 && character < 3)
        slide_window(character, grid);
}

/* Draws a magic list's scrollbar for the whole list instead of the window,
   with whichever of the game's two scrollbar functions the call was for. */
static void draw_list_scrollbar(int character, short *bar, DWORD alpha, DWORD draw)
{
    short total = bar[BAR_TOTAL_ROWS], top = bar[BAR_TOP_ROW];

    if (character >= 0 && character < 3 && list_rows(character) > WINDOW_ROWS) {
        bar[BAR_TOTAL_ROWS] = (short)list_rows(character);
        bar[BAR_TOP_ROW] = (short)(window_base[character] + top);
    }
    ((void (__cdecl *)(short *, DWORD))draw)(bar, alpha);
    bar[BAR_TOTAL_ROWS] = total;
    bar[BAR_TOP_ROW] = top;
}

static void __cdecl battle_scrollbar_hook(short *bar, DWORD alpha)
{
    draw_list_scrollbar(*(WORD *)ADDR_BATTLE_MENU_ACTOR, bar, alpha, FN_DRAW_SCROLLBAR);
}

