#define WIDE_SITE_COUNT         ((int)(sizeof wide_sites / sizeof wide_sites[0]))
#define WIDE_PLAN_ROWS          272             /* the rows of the architect's plan; the rest are the fed form's own */
#define WIDE_SITE_BYTES         24
#define WIDE_ROUTINES_START     0x006cbe5fu     /* remove, find, (a small routine between), add: 006cbe5f-006cc0e9 */
#define WIDE_ROUTINES_END       0x006cc0eau
#define WIDE_ROUTINE_OPERANDS   16              /* operands naming the old list inside them: they stay, unreached */
