static BOOL bytes_are(DWORD address, const BYTE *bytes, int count);
static BOOL wide_call_goes_to(DWORD site, void *target);
static DWORD wide_entry_target;                 /* ... and where it leads */

/* Is row `s` of the table WRITTEN in the form the switch takes? The data word of stage 2: never.
   The entry of remove: in the plan's own form only. The three calls at the table's end: in the
   fed form only. Everything else: always. (A row that is not written is not compared either,
   but for the data word, which is reported, and the entry of remove, which wide_entry_look saw.) */
static BOOL wide_site_written(int s)
{
    int kind = wide_sites[s].target;

    return kind == WIDE_T_LATER ? FALSE : kind == WIDE_T_REMOVE ? !wide_fed : kind == WIDE_T_REMOVE_FED ? wide_fed != 0 : TRUE;
}

static void *wide_target(int target)
{
    return target == WIDE_T_REMOVE || target == WIDE_T_REMOVE_FED ? (void *)wide_game_remove : target == WIDE_T_FIND ? (void *)wide_game_find
         : target == WIDE_T_ADD ? (void *)wide_game_add : target == WIDE_T_REMOVE_ONE ? (void *)wide_game_remove_one
         : target == WIDE_T_ADD_OLD ? (void *)wide_game_add_old : target == WIDE_T_REMOVE_OLD ? (void *)wide_game_remove_old : NULL;
}

/* One string of the table as bytes. NN NN NN NN: the list's address; RR RR RR RR: the distance
   from the byte after them to `target`. Returns the count of bytes, or -1 if the text is not
   pairs of hex digits and whole groups of four. */
static int wide_site_parse(const char *text, BYTE *bytes, DWORD address, void *target)
{
    int n = 0, group = 0;
    char kind = 0;

    while (*text) {
        int value;

        if (*text == ' ') {
            text++;
            continue;
        }
        if (n == WIDE_SITE_BYTES || !text[1])
            return -1;
        if ((text[0] == 'N' && text[1] == 'N') || (text[0] == 'R' && text[1] == 'R')) {
            DWORD whole;

            if (group && kind != text[0])
                return -1;
            if (text[0] == 'R' && !target)
                return -1;
            kind = text[0];
            whole = kind == 'N' ? (DWORD)wide_list : (DWORD)target - (address + (DWORD)(n - group) + 4);
            value = (int)(whole >> (8 * group) & 0xff);
            group = (group + 1) & 3;
        } else {
            int high = hex_digit(text[0]), low = hex_digit(text[1]);

            if (group || high < 0 || low < 0)
                return -1;
            value = high << 4 | low;
        }
        bytes[n++] = (BYTE)value;
        text += 2;
    }
    return group ? -1 : n;
}

/* Is the byte at `address` one that a site of the table replaces, in the form the switch takes? */
static BOOL wide_on_a_site(DWORD address)
{
    int s;

    for (s = 0; s < WIDE_SITE_COUNT; s++)
        if (wide_site_written(s) && address >= wide_sites[s].address && address < wide_sites[s].address + wide_site_length[s])
            return TRUE;
    return FALSE;
}

/* The game's code read through for the address of the old list. *inside: how many lie in the
   three routines; *stray: the first that lies neither there nor (`patched` FALSE: before the
   switch) on a site of the table. Returns the count of all. */
static int wide_scan_operands(BOOL patched, int *inside, DWORD *stray)
{
    const BYTE *text = (const BYTE *)WIDE_TEXT_START;
    DWORD i;
    int all = 0;

    *inside = 0;
    *stray = 0;
    for (i = 0; i + 4 <= WIDE_TEXT_BYTES; i++) {
        DWORD at = WIDE_TEXT_START + i;

        if (text[i] != 0x34 || text[i + 1] != 0x02 || text[i + 2] != 0xdc || text[i + 3] != 0x00)
            continue;
        all++;
        if (at >= WIDE_ROUTINES_START && at + 4 <= WIDE_ROUTINES_END)
            ++*inside;
        else if ((patched || !wide_on_a_site(at) || !wide_on_a_site(at + 3)) && !*stray)
            *stray = at;
    }
    return all;
}

static BOOL wide_call_goes_to(DWORD site, void *target)
{
    const BYTE *p = (const BYTE *)site;

    return !IsBadReadPtr(p, 5) && p[0] == 0xe8 && site + 5 + *(const DWORD *)(p + 1) == (DWORD)target;
}

/* The DLL's own hooks the switch depends on: NULL if every one is in, else which is not.
   (`new_game_too` FALSE: all but the new game's, which the switch puts in itself if it must.) */
static const char *wide_hook_missing(BOOL new_game_too)
{
    if (!wide_call_goes_to(ADDR_LOADER_CALL_1, kernel_loader_hook) || !wide_call_goes_to(ADDR_LOADER_CALL_2, kernel_loader_hook))
        return "the DLL's hook on the kernel loader's two calls (00408e70, 00409097: the starting stock comes with a kernel load)";
    if (new_game_too && !wide_call_goes_to(SITE_NEW_GAME, new_game_hook))
        return "the DLL's hook on the new game (00409758)";
    if (!wide_call_goes_to(SITE_LOAD_SLOT, load_slot_hook))
        return "the DLL's hook on the load of a slot (00722198)";
    if (!wide_call_goes_to(SITE_LOAD_ACCEPTED, load_accepted_hook))
        return "the DLL's hook on the accepted load (0072220b)";
    if (!wide_call_goes_to(SITE_SAVE_PREPARE, save_prepare_hook))
        return "the DLL's hook in the game's save writer (006feba5: the picture is painted there)";
    return NULL;
}

